def distancia_edicion(a: str, b: str) -> int:
    if len(a) < len(b):
        a, b = b, a

    prev = list(range(len(b) + 1))

    for i, ca in enumerate(a, 1):
        curr = [i] + [0] * len(b)

        for j, cb in enumerate(b, 1):
            costo = 0 if ca == cb else 1
            curr[j] = min(
                prev[j] + 1,       # borrado
                curr[j - 1] + 1,   # inserción
                prev[j - 1] + costo  # sustitución
            )

        prev = curr

    return prev[-1]

def fusionar(intervalos):
    if not intervalos:
        return []

    ordenados = sorted((min(inicio, fin), max(inicio, fin)) for inicio, fin in intervalos)

    resultado = []
    for inicio, fin in ordenados:
        if not resultado or inicio > resultado[-1][1]:
            resultado.append((inicio, fin))
        else:
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], fin))

    return resultado

def mochila(pesos, valores, capacidad):
    if capacidad < 0:
        return 0

    dp = [0] * (capacidad + 1)

    for peso, valor in zip(pesos, valores):
        if peso < 0 or valor < 0:
            continue

        for c in range(capacidad, peso - 1, -1):
            dp[c] = max(dp[c], dp[c - peso] + valor)

    return dp[capacidad]

import heapq

def dijkstra(grafo, origen):
    distancias = {origen: 0}
    cola = [(0, origen)]

    while cola:
        distancia_actual, nodo = heapq.heappop(cola)

        if distancia_actual > distancias.get(nodo, float("inf")):
            continue

        for vecino, peso in grafo.get(nodo, []):
            nueva_distancia = distancia_actual + peso

            if nueva_distancia < distancias.get(vecino, float("inf")):
                distancias[vecino] = nueva_distancia
                heapq.heappush(cola, (nueva_distancia, vecino))

    return distancias

def romano_a_entero(s):
    valores = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    s = s.upper()
    total = 0

    for i in range(len(s)):
        valor_actual = valores[s[i]]

        if i + 1 < len(s) and valor_actual < valores[s[i + 1]]:
            total -= valor_actual
        else:
            total += valor_actual

    return total

def islas(matriz):
    if not matriz:
        return 0

    filas = len(matriz)
    visitadas = set()
    total = 0

    for i in range(filas):
        for j in range(len(matriz[i])):
            if matriz[i][j] == 1 and (i, j) not in visitadas:
                total += 1

                pila = [(i, j)]
                visitadas.add((i, j))

                while pila:
                    x, y = pila.pop()

                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy

                        if (
                            0 <= nx < filas
                            and 0 <= ny < len(matriz[nx])
                            and matriz[nx][ny] == 1
                            and (nx, ny) not in visitadas
                        ):
                            visitadas.add((nx, ny))
                            pila.append((nx, ny))

    return total
